import{_ as a,c as i,o as t,a2 as s}from"./chunks/framework.CIiVzG-O.js";const u=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"guide/troubleshooting.md","filePath":"guide/troubleshooting.md","lastUpdated":1784988047000}'),o={name:"guide/troubleshooting.md"};function n(r,e,l,p,h,c){return t(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><p>This page collects common problems and how to resolve them.</p><h2 id="application-won-t-start-or-crashes-on-launch" tabindex="-1">Application won&#39;t start or crashes on launch <a class="header-anchor" href="#application-won-t-start-or-crashes-on-launch" aria-label="Permalink to &quot;Application won&#39;t start or crashes on launch&quot;">​</a></h2><p>Symptoms: Minesweeper does not open, crashes immediately, or shows an unexpected error.</p><p>Steps to try:</p><ol><li>Ensure your device meets the minimum requirements (iOS/iPadOS 15+, macOS 15+).</li><li>Force-quit and relaunch the app.</li><li>Restart your device.</li><li>Reinstall the app from the App Store.</li><li>If problems persist, open an issue on the project repository with details.</li></ol><h2 id="performance-issues" tabindex="-1">Performance issues <a class="header-anchor" href="#performance-issues" aria-label="Permalink to &quot;Performance issues&quot;">​</a></h2><p>If the game is laggy or slow:</p><ol><li>Close other heavy applications.</li><li>On Mac, check Activity Monitor for high CPU usage.</li><li>On older devices, try a smaller board size (Beginner difficulty).</li></ol><h2 id="view-logs" tabindex="-1">View logs <a class="header-anchor" href="#view-logs" aria-label="Permalink to &quot;View logs&quot;">​</a></h2><p>To troubleshoot crashes, application logs are useful. In sandboxed (App Store) builds on Mac, check:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/Library/Containers/com.w3cub.minesweeper/Data/Library/Logs/minesweeper/minesweeper.log</span></span></code></pre></div><p>On iOS/iPadOS, connect your device to a Mac and use Console.app to view logs, filtering by &quot;Minesweeper&quot;.</p><h2 id="resetting-the-app" tabindex="-1">Resetting the app <a class="header-anchor" href="#resetting-the-app" aria-label="Permalink to &quot;Resetting the app&quot;">​</a></h2><p>To reset settings and clear local data (Mac):</p><ol><li>Quit Minesweeper</li><li>Remove the container (careful — this deletes all settings and game data):</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Containers/com.w3cub.minesweeper</span></span></code></pre></div><ol start="3"><li>Reopen Minesweeper and reconfigure.</li></ol><p>On iPhone/iPad, delete and reinstall the app to reset all data.</p><h2 id="report-an-issue" tabindex="-1">Report an issue <a class="header-anchor" href="#report-an-issue" aria-label="Permalink to &quot;Report an issue&quot;">​</a></h2><p>When opening an issue, include:</p><ul><li>Device type (iPhone, iPad, or Mac)</li><li>OS version (Settings → General → About)</li><li>Minesweeper version (Settings → About)</li><li>Steps to reproduce</li><li>Logs or screenshots if available</li></ul><p>This helps maintainers identify and fix the problem faster.</p>',23)])])}const g=a(o,[["render",n]]);export{u as __pageData,g as default};
